/* ═══════════════════════════════════════════════════════════
   coastline.js — the shape of the world, in 220 KB.

   Natural Earth 1:50m land polygons and country borders, taken
   from the `world-atlas` package (public domain), quantised to
   1/64° (≈1.7 km), delta-coded, zig-zag varint-packed and
   base64'd. That is 1420 land rings / 60 500 points and 187
   border lines / 19 400 points — enough detail that Corsica,
   the Aleutians and the Danish straits all survive at globe
   scale, in less than half the weight of the source GeoJSON.

   The globe is the one place in this project where invented
   geometry would be a lie, so this is the one place that ships
   real data.
   ═══════════════════════════════════════════════════════════ */

/* Reverses the packing: base64 → bytes → varints → zig-zag →
   running sums → [lon, lat] pairs in a flat Float32Array per ring. */
function unpack(b64) {
  const bin = atob(b64);
  const n = bin.length;
  const bytes = new Uint8Array(n);
  for (let i = 0; i < n; i++) bytes[i] = bin.charCodeAt(i);

  let p = 0;
  const next = () => {
    let shift = 0, v = 0, b;
    do { b = bytes[p++]; v |= (b & 127) << shift; shift += 7; } while (b & 128);
    return (v >>> 1) ^ -(v & 1);            /* zig-zag decode */
  };

  const ringCount = next();
  const rings = new Array(ringCount);
  for (let r = 0; r < ringCount; r++) {
    const pts = next();
    const out = new Float32Array(pts * 2);
    let x = 0, y = 0;
    for (let i = 0; i < pts; i++) {
      x += next(); y += next();
      out[i * 2]     = x / 64 - 180;        /* longitude */
      out[i * 2 + 1] = y / 64 - 90;         /* latitude  */
    }
    rings[r] = out;
  }
  return rings;
}

let landCache = null, borderCache = null;
export const land    = () => (landCache   ||= unpack(LAND));
export const borders = () => (borderCache ||= unpack(BORDER));

